INSERT INTO `egc_recruitment_roles` (`sno`, `jobrole_name`, `status`, `created_by`, `created_at`, `updated_by`, `updated_at`, `role_description`, `mandatory_skills`, `preferred_skills`, `responsibilities`, `minimum_experience`, `education_requirements`, `seniority`) VALUES
(1, 'Business Development Executive', 0, 1, '2024-07-20 06:58:33', 1, '2026-08-25 00:50:27', 'Own revenue-oriented business development activities by identifying prospects, qualifying opportunities, building relationships, presenting solutions, negotiating commercial terms, and maintaining a healthy sales pipeline.', 'lead generation; prospecting; B2B sales; consultative selling; lead qualification; CRM; negotiation; proposal writing; relationship management; communication; presentation', 'LinkedIn Sales Navigator; HubSpot; Salesforce; Zoho CRM; Microsoft Excel; Google Workspace; proposal tools', 'Generate and qualify leads; conduct discovery calls and meetings; prepare proposals and quotations; follow up opportunities; update CRM; negotiate and close deals; coordinate handover to delivery; report pipeline and conversion metrics.', 1.00, 'Bachelor\'s degree or diploma in Business, Marketing, Communications, or related discipline; relevant sales experience may substitute for formal education.', 'Executive / Individual Contributor'),
(2, 'Senior Business Development  Executive', 0, 1, '2024-07-20 06:58:39', 1, '2026-08-25 00:50:27', 'Own revenue-oriented business development activities by identifying prospects, qualifying opportunities, building relationships, presenting solutions, negotiating commercial terms, and maintaining a healthy sales pipeline. The senior level is expected to handle complex work, mentor peers and contribute to process or technical decisions.', 'lead generation; prospecting; B2B sales; consultative selling; lead qualification; CRM; negotiation; proposal writing; relationship management; communication; presentation', 'LinkedIn Sales Navigator; HubSpot; Salesforce; Zoho CRM; Microsoft Excel; Google Workspace; proposal tools', 'Generate and qualify leads; conduct discovery calls and meetings; prepare proposals and quotations; follow up opportunities; update CRM; negotiate and close deals; coordinate handover to delivery; report pipeline and conversion metrics.', 3.00, 'Bachelor\'s degree or diploma in Business, Marketing, Communications, or related discipline; relevant sales experience may substitute for formal education.', 'Senior / Individual Contributor'),
(3, 'Tele caller', 0, 1, '2024-07-20 06:58:45', 1, '2026-08-25 00:50:27', 'Provide responsive customer support, resolve service issues and maintain accurate case records while protecting customer experience and satisfaction.', 'customer service; communication; active listening; ticketing; problem solving; CRM; email/chat; conflict resolution; documentation', 'CRM; Zendesk/Freshdesk; Microsoft Excel; Google Workspace; telephony/chat systems', 'Handle inbound queries; troubleshoot issues; document interactions; escalate appropriately; follow SLAs; conduct follow-ups; collect feedback; maintain service quality metrics.', 1.00, 'Bachelor\'s degree or diploma in Business, Marketing, Communications, or related discipline; relevant sales experience may substitute for formal education.', 'Executive / Individual Contributor'),
(4, 'Marketing Executive', 0, 1, '2024-07-20 06:58:51', 1, '2026-08-25 00:50:27', 'Execute multi-channel marketing campaigns that increase qualified awareness, engagement and leads across digital and offline channels.', 'digital marketing; campaign management; social media; content marketing; SEO basics; Google Analytics; email marketing; lead generation; copywriting; Excel', 'Google Analytics 4; Google Ads; Meta Ads Manager; Canva; HubSpot; Mailchimp; Excel', 'Plan campaigns; create briefs and content calendars; coordinate creatives; manage social channels; track campaign performance; support lead generation; report CAC, CPL, CTR and conversion metrics.', 1.00, 'Bachelor\'s degree or diploma in Business, Marketing, Communications, or related discipline; relevant sales experience may substitute for formal education.', 'Executive / Individual Contributor'),
(5, 'Marketing Manager', 0, 1, '2024-07-20 06:58:57', 1, '2026-08-25 00:50:27', 'Lead marketing strategy and execution across acquisition, brand, content and performance channels with measurable pipeline and revenue outcomes.', 'marketing strategy; demand generation; performance marketing; SEO; SEM; analytics; campaign planning; budgeting; team leadership; CRM', 'Google Analytics 4; Google Ads; Meta Ads Manager; HubSpot; Salesforce; Canva; Excel; Looker Studio', 'Set marketing plans and KPIs; allocate budgets; lead campaigns; manage agencies and vendors; align marketing with sales; monitor funnel metrics; optimize CAC, CPL, conversion and ROI; coach team members.', 5.00, 'Bachelor\'s degree or diploma in Business, Marketing, Communications, or related discipline; relevant sales experience may substitute for formal education.', 'Manager'),
(6, 'Business Development Manager', 0, 1, '2024-07-20 06:59:04', 1, '2026-08-25 00:50:27', 'Own revenue-oriented business development activities by identifying prospects, qualifying opportunities, building relationships, presenting solutions, negotiating commercial terms, and maintaining a healthy sales pipeline. The manager level is expected to own planning, performance and team or stakeholder leadership.', 'lead generation; prospecting; B2B sales; consultative selling; lead qualification; CRM; negotiation; proposal writing; relationship management; communication; presentation', 'LinkedIn Sales Navigator; HubSpot; Salesforce; Zoho CRM; Microsoft Excel; Google Workspace; proposal tools', 'Generate and qualify leads; conduct discovery calls and meetings; prepare proposals and quotations; follow up opportunities; update CRM; negotiate and close deals; coordinate handover to delivery; report pipeline and conversion metrics.', 5.00, 'Bachelor\'s degree or diploma in Business, Marketing, Communications, or related discipline; relevant sales experience may substitute for formal education.', 'Manager'),
(7, 'HR Senior Executive', 0, 1, '2024-07-20 06:59:10', 1, '2026-08-25 00:50:27', 'Support end-to-end HR operations and employee lifecycle activities with emphasis on recruitment, documentation, employee relations, compliance and HR reporting. The senior level is expected to handle complex work, mentor peers and contribute to process or technical decisions.', 'recruitment; sourcing; screening; interviewing; onboarding; employee records; HR policies; attendance; HRMS; Excel; communication', 'HRMS; ATS; Microsoft Excel; Microsoft Office; Google Workspace; payroll/attendance systems', 'Coordinate hiring and onboarding; maintain personnel records; support attendance and HR operations; handle employee queries; coordinate training; prepare HR reports; support policy and compliance activities.', 3.00, 'Bachelor\'s degree in Human Resources, Business Administration, Psychology, or related discipline; HR certification is a plus.', 'Senior / Individual Contributor'),
(8, 'HR Executive', 0, 1, '2024-07-20 06:59:18', 1, '2026-08-25 00:50:27', 'Execute day-to-day human resources operations including recruitment coordination, employee documentation, onboarding, HR records and employee support.', 'recruitment coordination; sourcing; screening; onboarding; HR documentation; employee records; HRMS; Excel; communication', 'ATS; HRMS; Microsoft Excel; Microsoft Office; Google Workspace', 'Schedule interviews; maintain candidate and employee records; coordinate onboarding; prepare HR letters; update HRMS; support attendance and leave administration; respond to employee queries.', 1.00, 'Bachelor\'s degree in Human Resources, Business Administration, Psychology, or related discipline; HR certification is a plus.', 'Executive / Individual Contributor'),
(9, 'HR Manager', 0, 1, '2024-07-20 06:59:32', 1, '2026-08-25 00:50:27', 'Lead HR operations and workforce initiatives covering recruitment, employee relations, policy implementation, performance, compliance and people reporting.', 'HR strategy; workforce planning; recruitment; employee relations; performance management; HR policies; compliance; HRMS; analytics; leadership', 'HRMS; ATS; Microsoft Excel; Power BI; Microsoft Office; payroll systems', 'Plan workforce needs; lead recruitment; manage employee relations; oversee onboarding and performance processes; maintain HR policies; monitor compliance; analyze people metrics; coach HR staff.', 5.00, 'Bachelor\'s degree in Human Resources, Business Administration, Psychology, or related discipline; HR certification is a plus.', 'Manager'),
(10, 'HR Recruiter', 0, 1, '2024-07-20 06:59:40', 1, '2026-08-25 00:50:27', 'Source, assess and coordinate candidates against approved company vacancies using structured screening, interview coordination and evidence-based candidate evaluation.', 'talent sourcing; Boolean search; screening; interviewing; ATS; candidate assessment; stakeholder communication; LinkedIn; recruitment analytics', 'ATS; LinkedIn Recruiter; Naukri; Indeed; Microsoft Excel; Google Workspace', 'Source candidates; screen resumes; conduct initial assessments; maintain candidate pipelines; coordinate interviews; capture feedback; communicate with hiring managers; track time-to-fill and funnel metrics.', 1.00, 'Bachelor\'s degree in Human Resources, Business Administration, Psychology, or related discipline; HR certification is a plus.', 'Executive / Individual Contributor'),
(11, 'Accounts Executive', 0, 1, '2024-07-20 06:59:46', 1, '2026-08-25 00:50:27', 'Maintain accurate accounting records and support transaction processing, reconciliations, invoicing, payables, receivables and financial reporting.', 'bookkeeping; journal entries; accounts payable; accounts receivable; bank reconciliation; GST basics; TDS basics; invoicing; Excel; Tally', 'Tally Prime; Zoho Books; QuickBooks; SAP/ERP; Microsoft Excel; GST portals', 'Record transactions; reconcile bank and ledger accounts; process invoices; follow up receivables; support payables; maintain vouchers; assist GST/TDS documentation; prepare periodic reports.', 1.00, 'Bachelor\'s degree in Commerce, Accounting, Finance, or related discipline; Tally/ERP certification preferred.', 'Executive / Individual Contributor'),
(12, 'Account Senior Executive', 0, 1, '2024-07-20 06:59:53', 1, '2026-08-25 00:50:27', 'Handle senior-level accounting operations including reconciliations, closing support, statutory documentation, payables/receivables and financial controls.', 'general ledger; reconciliations; month-end close; AP; AR; GST; TDS; audit support; ERP; Excel', 'Tally Prime; SAP; Oracle; Zoho Books; Microsoft Excel; GST portals', 'Review entries; perform reconciliations; support month-end closing; manage AP/AR aging; prepare schedules; coordinate audits; support statutory filings; improve accounting controls.', 3.00, 'Bachelor\'s degree in Commerce, Accounting, Finance, or related discipline; Tally/ERP certification preferred.', 'Senior / Individual Contributor'),
(13, 'Account Manager', 0, 1, '2024-07-20 07:00:01', 1, '2026-08-25 00:50:27', 'Oversee accounting operations, financial controls, reporting and statutory coordination while ensuring accurate and timely books of accounts. The manager level is expected to own planning, performance and team or stakeholder leadership.', 'financial accounting; month-end close; financial reporting; budgeting; GST; TDS; audit; internal controls; ERP; team leadership', 'SAP; Oracle; Tally Prime; Power BI; Microsoft Excel; ERP reporting', 'Lead accounting team; review ledgers and reconciliations; oversee closing; monitor cash, AP and AR; coordinate audits and statutory compliance; prepare management reports; strengthen controls.', 5.00, 'Bachelor\'s degree in Commerce, Accounting, Finance, or related discipline; Tally/ERP certification preferred.', 'Manager'),
(14, 'IT Executive', 0, 1, '2024-07-20 07:00:07', 1, '2026-08-25 00:50:27', 'Provide day-to-day IT support, endpoint administration, user access management, troubleshooting and basic infrastructure operations.', 'IT support; Windows; hardware; networking; troubleshooting; Active Directory; Microsoft 365; ticketing; cybersecurity basics', 'Microsoft 365; Active Directory; Windows Server; Jira Service Management; TeamViewer/AnyDesk; antivirus tools', 'Resolve user incidents; provision accounts and devices; troubleshoot hardware/software/network issues; manage tickets; support backups and endpoint security; maintain IT asset records.', 1.00, 'Relevant diploma, degree, trade qualification, or equivalent practical experience appropriate to the role.', 'Executive / Individual Contributor'),
(15, 'IT Senior Executive', 0, 1, '2024-07-20 07:00:15', 1, '2026-08-25 00:50:27', 'Own advanced IT support and endpoint/infrastructure operations, resolving complex incidents and maintaining secure, reliable workplace technology. The senior level is expected to handle complex work, mentor peers and contribute to process or technical decisions.', 'advanced troubleshooting; Windows Server; Active Directory; Microsoft 365; networking; TCP/IP; DNS; DHCP; endpoint security; backup; ITIL', 'Microsoft 365; Active Directory; Windows Server; Intune; Jira Service Management; monitoring tools', 'Handle escalated incidents; administer users and endpoints; monitor infrastructure; maintain security controls; coordinate vendors; document changes; support backup and disaster recovery procedures.', 3.00, 'Relevant diploma, degree, trade qualification, or equivalent practical experience appropriate to the role.', 'Senior / Individual Contributor'),
